for await (const message of query({
  prompt: 'Create a test file in /tmp and then delete it',
  options: {
    canUseTool: async (toolName, input) => {
      if (toolName === 'AskUserQuestion') return handleQuestions(input);
      const ok = await askUser(`Allow ${toolName}? ${JSON.stringify(input)}`);
      return ok
        ? { behavior: 'allow', updatedInput: input }      // run (optionally modified)
        : { behavior: 'deny', message: 'User denied this action' }; // Claude sees this
    }
  }
})) {
  if ('result' in message) console.log(message.result);
}

async for message in query(
    prompt='Find and fix the bug causing test failures in the auth module',
    options=ClaudeAgentOptions(
        allowed_tools=['Read', 'Edit', 'Bash', 'Glob', 'Grep'],  # auto-approved
        setting_sources=['project'],   # load CLAUDE.md, skills, hooks
        max_turns=30,                  # prevent runaway sessions
        effort='high',
    ),
):
    if isinstance(message, ResultMessage):
        session_id = message.session_id
        if message.subtype == 'success':
            print(message.result)
        elif message.subtype == 'error_max_turns':
            print('Hit turn limit; resume', session_id)

